import sys

def find_leaf_nodes(preorder):
    n = len(preorder)
    if n == 0:
        return []
    if n == 1:
        return [preorder[0]]

    is_leaf = [True] * n

    for i in range(n - 1):
        for j in range(i + 1, n):
            if preorder[j] > preorder[i]:
                is_leaf[i] = False
                break

    return [preorder[i] for i in range(n) if is_leaf[i]]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print("")
        return
    preorder = list(map(int, data[1:n+1]))
    leaves = find_leaf_nodes(preorder)
    print(" ".join(map(str, leaves)))

if __name__ == "__main__":
    main()
